try {
  const body = $input.first().json.body || $input.first().json;
  const toolCallList = body?.message?.toolCallList || [];
  if (toolCallList.length === 0) throw new Error('empty toolCallList');
  const toolCall = toolCallList[0];
  const toolCallId = toolCall.id || 'unknown';
  let args = {};
  try { args = typeof toolCall.function?.arguments === 'string' ? JSON.parse(toolCall.function.arguments) : (toolCall.function?.arguments || {}); } catch(e) { args = {}; }
  const doctorName = (args.doctorName || '').trim();
  const specialization = (args.specialization || '').trim();
  return [{ json: { toolCallId, doctorName, specialization, error: false } }];
} catch(e) {
  return [{ json: { toolCallId: 'unknown', error: true, result: 'İsteğinizi işlerken bir hata oluştu. Lütfen tekrar deneyin.' } }];
}

const toolCallId = $('Argümanları Çıkar').first().json.toolCallId;
const doctors = $input.all().map(i => i.json).filter(d => d.full_name);

if (doctors.length === 0) {
  const searched = $('Argümanları Çıkar').first().json.doctorName || $('Argümanları Çıkar').first().json.specialization || 'belirtilen kriterlere';
  return [{ json: { toolCallId, result: `${searched} uygun aktif doktor bulunamadı. Başka bir uzmanlık alanı tercih eder misiniz?` } }];
}

const dayMap = { mon: 'Pzt', tue: 'Sal', wed: 'Çar', thu: 'Per', fri: 'Cum', sat: 'Cmt', sun: 'Paz' };

const descriptions = doctors.map(d => {
  let info = `${d.full_name} (${d.specialization})`;
  if (d.working_hours) {
    try {
      const wh = typeof d.working_hours === 'string' ? JSON.parse(d.working_hours) : d.working_hours;
      const days = Object.entries(wh).filter(([, v]) => v).map(([k, v]) => `${dayMap[k] || k}: ${v}`).join(', ');
      if (days) info += ` — Çalışma saatleri: ${days}`;
    } catch(e) {}
  }
  return info;
});

return [{ json: { toolCallId, result: `Klinikimizde bulunan doktorlar: ${descriptions.join('. ')}.` } }];
